public class ConPOO {
    public static void main(String[] args) {
        // Cada alumno es un objeto con sus propios datos
        Alumno a1 = new Alumno("Ana", "ana@email.com");
        a1.setNota(8.5);

        Alumno a2 = new Alumno("Carlos", "carlos@email.com");
        a2.setNota(7.0);

        Alumno a3 = new Alumno("Maria", "maria@email.com");
