        return nombre + " (" + email + ")";
    }

    public static void main(String[] args) {
        Alumno a1 = new Alumno("Ana", "ana@email.com");
        Alumno a2 = new Alumno("Carlos", "carlos@email.com");

        // Asignar notas
        a1.notaMedia = 8.5;
        a2.notaMedia = 4.0;

        a1.mostrarInfo();
        System.out.println("Aprobado: " + a1.estaAprobado());

        a2.mostrarInfo();
