        this.notaMedia = notaMedia;
    }

    // Constructor con nota por defecto
    public Alumno(String nombre, String email) {
        this(nombre, email, 0.0);
    }

    // Constructor solo con nombre
    public Alumno(String nombre) {
        this(nombre, "sin@email.com");
    }

    void mostrarInfo() {
        System.out.println(nombre + " - " + email + " - Nota: " + notaMedia);
    }

    public static void main(String[] args) {
        Alumno a1 = new Alumno("Ana", "ana@email.com", 8.5);
        Alumno a2 = new Alumno("Carlos", "carlos@email.com");
        Alumno a3 = new Alumno("Maria");

        a1.mostrarInfo();
        a2.mostrarInfo();
        a3.mostrarInfo();
    }
}

