public class CuentaBancaria {
    private String titular;
    private double saldo;

    public CuentaBancaria(String titular, double saldoInicial) {
        this.titular = titular;
        this.saldo = saldoInicial;
    }

    public String getTitular() { return titular; }
    public double getSaldo() { return saldo; }

    public void ingresar(double cantidad) {
        if (cantidad > 0) {
            saldo += cantidad;
            System.out.println("Ingresado: " + cantidad + " EUR");
        }
    }

    public void retirar(double cantidad) {
        if (cantidad > 0 && cantidad <= saldo) {
            saldo -= cantidad;
            System.out.println("Retirado: " + cantidad + " EUR");
        } else {
            System.out.println("Saldo insuficiente.");
        }
    }

    public void mostrarInfo() {
        System.out.println(titular + " - Saldo: " + saldo + " EUR");
    }

    public static void main(String[] args) {
        CuentaBancaria cuenta = new CuentaBancaria("Ana", 1000);
        cuenta.ingresar(500);
        cuenta.retirar(200);
        cuenta.retirar(2000); // Saldo insuficiente
        cuenta.mostrarInfo();
    }
}

