public class Instituto {
    public static void main(String[] args) {
        Curso[] cursos = {
            new Curso("Java", 272, "Garcia"),
            new Curso("BD", 160, "Lopez"),
            new Curso("Redes", 120, "Martinez")
        };

        Alumno[] alumnos = {
            new Alumno("Ana", "ana@email.com"),
            new Alumno("Carlos", "carlos@email.com"),
            new Alumno("Maria", "maria@email.com"),
            new Alumno("Pedro", "pedro@email.com"),
            new Alumno("Laura", "laura@email.com"),
            new Alumno("David", "david@email.com")
        };

        double[] notas = {8.5, 4.0, 9.2, 7.0, 3.5, 6.8};
        for (int i = 0; i < alumnos.length; i++) {
            alumnos[i].setNotaMedia(notas[i]);
        }

        // Matricular alumnos en cursos
        for (int i = 0; i < 3; i++) cursos[0].matricularAlumno();
        for (int i = 0; i < 2; i++) cursos[1].matricularAlumno();
        for (int i = 0; i < 2; i++) cursos[2].matricularAlumno();

        // Resumen cursos
        System.out.println("=== CURSOS ===");
        for (Curso c : cursos) System.out.println(c.getResumen());

        // Alumnos aprobados
        System.out.println("\n=== APROBADOS ===");
        for (Alumno a : alumnos) {
            if (a.estaAprobado()) System.out.println(a.getNombre() + ": " + a.getNotaMedia());
        }

        // Media general
        double suma = 0;
        for (Alumno a : alumnos) suma += a.getNotaMedia();
        System.out.println("\nNota media general: " + (suma / alumnos.length));
    }
}
